-- Persistent OpenFuse browser session metadata and encrypted Playwright state.
create table if not exists public.moreai_browser_sessions (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  run_id uuid not null references public.agent_runs(id) on delete cascade,
  last_run_id uuid references public.agent_runs(id) on delete set null,
  origin_host text not null check (origin_host ~ '^[A-Za-z0-9.-]{1,253}$'),
  status text not null default 'active' check (status in ('active','closed','expired')),
  encrypted_state text,
  created_at timestamptz not null default now(),
  last_used_at timestamptz not null default now(),
  expires_at timestamptz not null,
  closed_at timestamptz,
  constraint moreai_browser_session_expiry_valid check (expires_at > created_at)
);
create index if not exists moreai_browser_sessions_owner_active_idx
  on public.moreai_browser_sessions(user_id,last_used_at desc) where status='active';
alter table public.moreai_browser_sessions enable row level security;
revoke all on public.moreai_browser_sessions from anon, authenticated;
grant select,insert,update,delete on public.moreai_browser_sessions to service_role;

create table if not exists public.moreai_browser_session_events (
  id uuid primary key default gen_random_uuid(),
  session_id uuid not null references public.moreai_browser_sessions(id) on delete cascade,
  user_id uuid not null references auth.users(id) on delete cascade,
  event_type text not null check (event_type in ('created','restored','state_saved','closed','expired')),
  metadata jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now()
);
create index if not exists moreai_browser_session_events_owner_idx
  on public.moreai_browser_session_events(user_id,created_at desc);
alter table public.moreai_browser_session_events enable row level security;
revoke all on public.moreai_browser_session_events from anon, authenticated;
grant select,insert on public.moreai_browser_session_events to service_role;

alter table public.moreai_customer_agent_configs add column if not exists preferred_model_id uuid references public.llm_models(id) on delete set null;
create index if not exists moreai_customer_agent_configs_preferred_model_idx on public.moreai_customer_agent_configs(preferred_model_id) where preferred_model_id is not null;
create or replace function public.moreai_enqueue_chat_run_with_config(p_user_id uuid,p_conversation_id uuid,p_content text,p_agent_key text,p_idempotency_key text,p_agent_config_id uuid) returns jsonb language plpgsql security definer set search_path='' as $function$
declare v_conversation public.conversations%rowtype; v_message public.conversation_messages%rowtype; v_run public.agent_runs%rowtype; v_config public.moreai_customer_agent_configs%rowtype;
begin
if p_user_id is null or p_conversation_id is null or p_content is null or length(btrim(p_content))=0 or length(p_content)>100000 or p_agent_key not in ('manus','toolcall') or p_idempotency_key is null or length(p_idempotency_key)<12 or length(p_idempotency_key)>128 or p_agent_config_id is null then raise exception 'invalid configured chat enqueue request' using errcode='22023'; end if;
select * into v_config from public.moreai_customer_agent_configs where id=p_agent_config_id and user_id=p_user_id and enabled=true for share;
if not found or v_config.runtime_key<>p_agent_key then raise exception 'agent configuration not found or runtime mismatch' using errcode='42501'; end if;
if v_config.preferred_model_id is not null and not exists(select 1 from public.llm_models m join public.llm_providers p on p.id=m.provider_id where m.id=v_config.preferred_model_id and m.enabled=true and p.enabled=true) then raise exception 'configured_model_is_not_enabled' using errcode='22023'; end if;
select * into v_conversation from public.conversations where id=p_conversation_id and user_id=p_user_id for update;
if not found then raise exception 'conversation not found' using errcode='42501'; end if;
select * into v_run from public.agent_runs where user_id=p_user_id and idempotency_key=p_idempotency_key;
if found then return jsonb_build_object('run',to_jsonb(v_run),'message',null,'replayed',true); end if;
insert into public.conversation_messages(conversation_id,user_id,role,content,metadata) values(p_conversation_id,p_user_id,'user',p_content,'{}'::jsonb) returning * into v_message;
insert into public.agent_runs(user_id,workspace_id,conversation_id,status,idempotency_key,input,max_attempts) values(p_user_id,v_conversation.workspace_id,p_conversation_id,'queued',p_idempotency_key,jsonb_build_object('prompt',p_content,'agent_key',p_agent_key,'agent_config',jsonb_build_object('id',v_config.id,'runtime_key',v_config.runtime_key,'name',v_config.name,'system_prompt',v_config.system_prompt,'tool_keys',to_jsonb(v_config.tool_keys),'preferred_model_id',v_config.preferred_model_id,'version',v_config.version),'conversation_id',p_conversation_id,'message_id',v_message.id),3) returning * into v_run;
update public.conversation_messages set run_id=v_run.id where id=v_message.id and user_id=p_user_id;
v_message.run_id:=v_run.id;
return jsonb_build_object('run',to_jsonb(v_run),'message',to_jsonb(v_message),'replayed',false);
end;
$function$;
revoke all on function public.moreai_enqueue_chat_run_with_config(uuid,uuid,text,text,text,uuid) from public,anon,authenticated;
grant execute on function public.moreai_enqueue_chat_run_with_config(uuid,uuid,text,text,text,uuid) to service_role;

-- Preserve the attachment-aware chat enqueue contract while adding an immutable model preference snapshot.
drop function if exists public.moreai_enqueue_chat_run_with_config(uuid,uuid,text,text,text,uuid);

create or replace function public.moreai_enqueue_chat_run_with_config(
    p_user_id uuid,
    p_conversation_id uuid,
    p_content text,
    p_agent_key text,
    p_idempotency_key text,
    p_agent_config_id uuid,
    p_attachment_ids uuid[] default '{}'::uuid[]
) returns jsonb
language plpgsql
security definer
set search_path = ''
as $function$
declare
    v_conversation public.conversations%rowtype;
    v_message public.conversation_messages%rowtype;
    v_run public.agent_runs%rowtype;
    v_config public.moreai_customer_agent_configs%rowtype;
    v_attachment_ids uuid[];
    v_attachment_count integer;
    v_agent_config_snapshot jsonb;
begin
    if p_user_id is null or p_conversation_id is null
       or p_content is null or length(btrim(p_content)) = 0 or length(p_content) > 100000
       or p_agent_key is null or p_agent_key not in ('manus','toolcall')
       or p_idempotency_key is null or length(p_idempotency_key) not between 12 and 128
       or p_agent_config_id is null or coalesce(cardinality(p_attachment_ids),0) > 10 then
        raise exception 'invalid_configured_chat_enqueue_request' using errcode = '22023';
    end if;

    select * into v_config from public.moreai_customer_agent_configs
     where id = p_agent_config_id and user_id = p_user_id and enabled = true for share;
    if not found or v_config.runtime_key <> p_agent_key then
        raise exception 'agent_configuration_not_found_or_runtime_mismatch' using errcode = '42501';
    end if;
    if v_config.preferred_model_id is not null and not exists (
        select 1 from public.llm_models m
        join public.llm_providers p on p.id = m.provider_id
        where m.id = v_config.preferred_model_id and m.enabled = true and p.enabled = true
    ) then
        raise exception 'configured_model_is_not_enabled' using errcode = '22023';
    end if;

    v_agent_config_snapshot := jsonb_build_object(
        'id', v_config.id,
        'runtime_key', v_config.runtime_key,
        'name', v_config.name,
        'system_prompt', v_config.system_prompt,
        'tool_keys', to_jsonb(v_config.tool_keys),
        'preferred_model_id', v_config.preferred_model_id,
        'version', v_config.version
    );

    select coalesce(array_agg(x order by x), '{}'::uuid[])
      into v_attachment_ids
      from (select distinct unnest(coalesce(p_attachment_ids, '{}'::uuid[])) as x) q;
    if cardinality(v_attachment_ids) <> coalesce(cardinality(p_attachment_ids),0) then
        raise exception 'duplicate_chat_attachment_id' using errcode = '22023';
    end if;

    select * into v_conversation from public.conversations
     where id = p_conversation_id and user_id = p_user_id and status = 'active' for update;
    if not found then raise exception 'conversation_not_found_or_inactive' using errcode = '42501'; end if;

    if cardinality(v_attachment_ids) > 0 then
        select count(*) into v_attachment_count from public.artifacts a
         where a.id = any(v_attachment_ids)
           and a.user_id = p_user_id
           and a.metadata->>'purpose' = 'chat_attachment'
           and a.metadata->>'conversation_id' = p_conversation_id::text
           and a.size_bytes between 1 and 2000000
           and a.mime_type in ('text/plain','text/markdown','text/csv','application/json',
             'application/pdf','image/jpeg','image/png','image/webp');
        if v_attachment_count <> cardinality(v_attachment_ids) then
            raise exception 'chat_attachment_not_owned_or_not_available' using errcode = '42501';
        end if;
    end if;

    select * into v_run from public.agent_runs
     where user_id = p_user_id and idempotency_key = p_idempotency_key;
    if found then
        if v_run.input->>'prompt' is distinct from p_content
           or v_run.input->>'agent_key' is distinct from p_agent_key
           or v_run.input->'agent_config' is distinct from v_agent_config_snapshot
           or coalesce(v_run.input->'attachment_ids','[]'::jsonb) is distinct from to_jsonb(v_attachment_ids) then
            raise exception 'chat_idempotency_key_payload_conflict' using errcode = '22023';
        end if;
        return jsonb_build_object('run',to_jsonb(v_run),'message',null,'replayed',true);
    end if;

    insert into public.conversation_messages(conversation_id,user_id,role,content,metadata)
    values(p_conversation_id,p_user_id,'user',p_content,'{}'::jsonb) returning * into v_message;
    insert into public.agent_runs(user_id,workspace_id,conversation_id,status,idempotency_key,input,max_attempts)
    values(
        p_user_id,v_conversation.workspace_id,p_conversation_id,'queued',p_idempotency_key,
        jsonb_build_object(
            'prompt',p_content,'agent_key',p_agent_key,'conversation_id',p_conversation_id,
            'message_id',v_message.id,'attachment_ids',to_jsonb(v_attachment_ids),
            'agent_config',v_agent_config_snapshot
        ),3
    ) returning * into v_run;
    update public.conversation_messages set run_id = v_run.id
     where id = v_message.id and user_id = p_user_id;
    v_message.run_id := v_run.id;
    if cardinality(v_attachment_ids) > 0 then
        insert into public.conversation_message_attachments(user_id,conversation_id,message_id,run_id,artifact_id)
        select p_user_id,p_conversation_id,v_message.id,v_run.id,x from unnest(v_attachment_ids) as x;
    end if;
    return jsonb_build_object('run',to_jsonb(v_run),'message',to_jsonb(v_message),'replayed',false);
end;
$function$;
revoke all on function public.moreai_enqueue_chat_run_with_config(uuid,uuid,text,text,text,uuid,uuid[])
  from public, anon, authenticated;
grant execute on function public.moreai_enqueue_chat_run_with_config(uuid,uuid,text,text,text,uuid,uuid[])
  to service_role;

-- Assessment-derived learning completion. Agents may start lessons, but only
-- server-graded successful assessments can complete them.
create or replace function public.moreai_learning_progress_update(
 p_user_id uuid,p_run_id uuid,p_lesson_id uuid,p_status text
) returns jsonb language plpgsql security invoker set search_path = ''
as $$
declare
 v_lesson public.learning_lessons%rowtype;
 v_progress public.learning_progress%rowtype;
 v_total integer;
 v_completed integer;
 v_percent numeric(5,2);
 v_path_status text;
begin
 if not exists(select 1 from public.agent_runs r where r.id=p_run_id and r.user_id=p_user_id) then
  raise exception 'learning_run_owner_mismatch' using errcode='42501';
 end if;
 if p_status <> 'in_progress' then
  raise exception 'learning_progress_completion_is_assessment_derived' using errcode='22023';
 end if;
 select * into v_lesson from public.learning_lessons where id=p_lesson_id and owner_user_id=p_user_id;
 if not found then raise exception 'learning_lesson_not_found' using errcode='P0002'; end if;

 insert into public.learning_enrollments(path_id,user_id,status)
 values(v_lesson.path_id,p_user_id,'active')
 on conflict(path_id,user_id) do update set
  status=case when public.learning_enrollments.status='completed' then 'completed' else 'active' end,
  updated_at=now();

 insert into public.learning_progress(
  user_id,path_id,module_id,lesson_id,status,progress_percent,last_run_id,started_at,completed_at,updated_at
 ) values(p_user_id,v_lesson.path_id,v_lesson.module_id,v_lesson.id,'in_progress',1,p_run_id,now(),null,now())
 on conflict(user_id,lesson_id) do update set
  status=case when public.learning_progress.status='completed' then 'completed' else 'in_progress' end,
  progress_percent=case when public.learning_progress.status='completed' then 100 else greatest(public.learning_progress.progress_percent,1) end,
  last_run_id=excluded.last_run_id,
  started_at=coalesce(public.learning_progress.started_at,now()),
  completed_at=case when public.learning_progress.status='completed' then public.learning_progress.completed_at else null end,
  updated_at=now()
 returning * into v_progress;

 select count(*),count(*) filter(where p.status='completed')
 into v_total,v_completed
 from public.learning_lessons l
 left join public.learning_progress p on p.lesson_id=l.id and p.user_id=p_user_id
 where l.path_id=v_lesson.path_id and l.owner_user_id=p_user_id;
 v_percent := case when v_total=0 then 0 else round((v_completed::numeric/v_total::numeric)*100,2) end;
 v_path_status := case when v_total>0 and v_completed=v_total then 'completed' else 'active' end;

 update public.learning_enrollments set
  status=case when v_path_status='completed' then 'completed' else 'active' end,
  completed_at=case when v_path_status='completed' then coalesce(completed_at,now()) else null end,
  updated_at=now()
 where path_id=v_lesson.path_id and user_id=p_user_id;
 update public.learning_paths set status=v_path_status,updated_at=now()
 where id=v_lesson.path_id and owner_user_id=p_user_id;

 insert into public.learning_run_artifacts(user_id,run_id,artifact_type,resource_id,payload)
 values(p_user_id,p_run_id,'progress',v_progress.id,jsonb_build_object(
  'lesson_id',v_lesson.id,'status',v_progress.status,'progress_percent',v_progress.progress_percent,
  'path_progress_percent',v_percent,'completed_lessons',v_completed,'total_lessons',v_total
 ))
 on conflict(run_id,artifact_type,resource_id) do update set payload=excluded.payload;

 return jsonb_build_object(
  'progress_id',v_progress.id,'lesson_id',v_lesson.id,'status',v_progress.status,
  'progress_percent',v_progress.progress_percent,'path_status',v_path_status,
  'path_progress_percent',v_percent,'completed_lessons',v_completed,'total_lessons',v_total
 );
end $$;

create or replace function public.moreai_learning_answer_assess(
 p_user_id uuid,p_run_id uuid,p_quiz_id uuid,p_answers jsonb,p_score numeric,p_feedback jsonb,p_rubric jsonb
) returns jsonb language plpgsql security invoker set search_path = ''
as $$
declare
 v_quiz public.learning_quizzes%rowtype;
 v_attempt public.learning_quiz_attempts%rowtype;
 v_assessment public.learning_assessments%rowtype;
 v_all_passed boolean := false;
 v_progress public.learning_progress%rowtype;
 v_total integer := 0;
 v_completed integer := 0;
 v_remaining integer := 0;
 v_path_percent numeric(5,2) := 0;
begin
 if not exists(select 1 from public.agent_runs r where r.id=p_run_id and r.user_id=p_user_id) then
  raise exception 'learning_run_owner_mismatch' using errcode='42501';
 end if;
 select * into v_quiz from public.learning_quizzes where id=p_quiz_id and owner_user_id=p_user_id;
 if not found then raise exception 'learning_quiz_not_found' using errcode='P0002'; end if;
 if jsonb_typeof(p_answers) is distinct from 'array' then
  raise exception 'learning_answers_invalid' using errcode='22023';
 end if;

 insert into public.learning_quiz_attempts(quiz_id,user_id,run_id,answers,score,passed,feedback)
 values(v_quiz.id,p_user_id,p_run_id,p_answers,greatest(0,least(100,p_score)),p_score>=v_quiz.pass_score,coalesce(p_feedback,'{}'::jsonb))
 on conflict(run_id,quiz_id) do update set
  answers=excluded.answers,score=excluded.score,passed=excluded.passed,feedback=excluded.feedback
 returning * into v_attempt;

 insert into public.learning_assessments(
  user_id,path_id,module_id,lesson_id,quiz_id,run_id,assessment_type,score,rubric,feedback
 ) values(
  p_user_id,v_quiz.path_id,v_quiz.module_id,v_quiz.lesson_id,v_quiz.id,p_run_id,'quiz',
  v_attempt.score,coalesce(p_rubric,'[]'::jsonb),coalesce(p_feedback,'{}'::jsonb)
 )
 on conflict(run_id,quiz_id) where quiz_id is not null do update set
  score=excluded.score,rubric=excluded.rubric,feedback=excluded.feedback
 returning * into v_assessment;

 insert into public.learning_run_artifacts(user_id,run_id,artifact_type,resource_id,payload)
 values(p_user_id,p_run_id,'assessment',v_assessment.id,jsonb_build_object(
  'quiz_id',v_quiz.id,'attempt_id',v_attempt.id,'score',v_attempt.score,'passed',v_attempt.passed
 ))
 on conflict(run_id,artifact_type,resource_id) do update set payload=excluded.payload;

 if v_attempt.passed then
  select not exists(
   select 1 from public.learning_quizzes q
   where q.lesson_id=v_quiz.lesson_id and q.owner_user_id=p_user_id
     and not exists(
      select 1 from public.learning_quiz_attempts a
      where a.quiz_id=q.id and a.user_id=p_user_id and a.passed=true
     )
  ) into v_all_passed;

  if v_all_passed then
   insert into public.learning_progress(
    user_id,path_id,module_id,lesson_id,status,progress_percent,last_run_id,started_at,completed_at,updated_at
   ) values(
    p_user_id,v_quiz.path_id,v_quiz.module_id,v_quiz.lesson_id,'in_progress',1,p_run_id,now(),null,now()
   )
   on conflict(user_id,lesson_id) do update set
    last_run_id=excluded.last_run_id,
    started_at=coalesce(public.learning_progress.started_at,now()),
    updated_at=now()
   returning * into v_progress;

   update public.learning_progress set
    status='completed',progress_percent=100,
    completed_at=coalesce(completed_at,now()),last_run_id=p_run_id,updated_at=now()
   where user_id=p_user_id and lesson_id=v_quiz.lesson_id
   returning * into v_progress;

   insert into public.learning_run_artifacts(user_id,run_id,artifact_type,resource_id,payload)
   values(p_user_id,p_run_id,'progress',v_progress.id,jsonb_build_object(
    'lesson_id',v_quiz.lesson_id,'status','completed','progress_percent',100,
    'completion_source','all_required_quizzes_passed'
   ))
   on conflict(run_id,artifact_type,resource_id) do update set payload=excluded.payload;
  end if;
 end if;

 select count(*),count(*) filter(where p.status='completed')
 into v_total,v_completed
 from public.learning_lessons l
 left join public.learning_progress p on p.lesson_id=l.id and p.user_id=p_user_id
 where l.path_id=v_quiz.path_id and l.owner_user_id=p_user_id;
 v_remaining := greatest(v_total-v_completed,0);
 v_path_percent := case when v_total=0 then 0 else round((v_completed::numeric/v_total::numeric)*100,2) end;
 if v_total>0 and v_remaining=0 then
  update public.learning_enrollments set status='completed',
   completed_at=coalesce(completed_at,now()),updated_at=now()
  where path_id=v_quiz.path_id and user_id=p_user_id;
  update public.learning_paths set status='completed',updated_at=now()
  where id=v_quiz.path_id and owner_user_id=p_user_id;
 end if;

 return jsonb_build_object(
  'attempt_id',v_attempt.id,'assessment_id',v_assessment.id,
  'score',v_attempt.score,'passed',v_attempt.passed,
  'lesson_completed',coalesce(v_progress.status='completed',false),
  'path_progress_percent',v_path_percent,'completed_lessons',v_completed,'total_lessons',v_total
 );
end $$;

revoke all on function public.moreai_learning_progress_update(uuid,uuid,uuid,text) from public,anon,authenticated;
revoke all on function public.moreai_learning_answer_assess(uuid,uuid,uuid,jsonb,numeric,jsonb,jsonb) from public,anon,authenticated;
grant execute on function public.moreai_learning_progress_update(uuid,uuid,uuid,text) to service_role;
grant execute on function public.moreai_learning_answer_assess(uuid,uuid,uuid,jsonb,numeric,jsonb,jsonb) to service_role;

-- Phase 09A: align the platform routing contract with OpenManus runtime task types.
-- Preserve the existing mutation signature and all authorization/audit gates.
create or replace function public.moreai_admin_mutate_llm_route(
  p_actor_user_id uuid,
  p_policy_id uuid,
  p_task_type text,
  p_model_id uuid,
  p_fallback_model_id uuid,
  p_priority integer,
  p_enabled boolean,
  p_correlation_id text default null
)
returns jsonb
language plpgsql
set search_path to 'public', 'pg_temp'
as $function$
declare
  v_policy public.llm_routing_policies%rowtype;
  v_action text;
begin
  if p_actor_user_id is null
    or p_task_type not in ('general', 'chat', 'planning')
    or p_model_id is null
    or p_priority < 0 then
    raise exception using errcode='22023', message='LLM_ROUTE_INVALID';
  end if;

  if not exists (
    select 1 from public.user_role_assignments ura
    join public.roles r on r.id=ura.role_id
    join public.role_permissions rp on rp.role_id=r.id
    join public.permissions p on p.id=rp.permission_id
    where ura.user_id=p_actor_user_id and ura.scope_type='platform'
      and ura.scope_id is null and (ura.expires_at is null or ura.expires_at>now())
      and r.scope='platform' and p.key='platform.models.manage'
  ) then
    raise exception using errcode='42501', message='ADMIN_PERMISSION_DENIED';
  end if;

  if p_enabled and not exists (
    select 1 from public.llm_models m
    join public.llm_providers pr on pr.id=m.provider_id
    where m.id=p_model_id and m.enabled=true and pr.enabled=true
  ) then
    raise exception using errcode='55000', message='LLM_PRIMARY_MODEL_NOT_READY';
  end if;

  if p_enabled and p_fallback_model_id is not null and not exists (
    select 1 from public.llm_models m
    join public.llm_providers pr on pr.id=m.provider_id
    where m.id=p_fallback_model_id and m.enabled=true and pr.enabled=true
  ) then
    raise exception using errcode='55000', message='LLM_FALLBACK_MODEL_NOT_READY';
  end if;

  if p_policy_id is null then
    insert into public.llm_routing_policies(
      scope_type,scope_id,task_type,model_id,priority,fallback_model_id,enabled
    ) values ('platform',null,p_task_type,p_model_id,p_priority,p_fallback_model_id,p_enabled)
    returning * into v_policy;
    v_action := 'llm.routing.create';
  else
    select * into v_policy from public.llm_routing_policies
    where id=p_policy_id and scope_type='platform' and scope_id is null for update;
    if not found then
      raise exception using errcode='P0002', message='LLM_ROUTE_NOT_FOUND';
    end if;
    update public.llm_routing_policies
    set task_type=p_task_type,model_id=p_model_id,priority=p_priority,
        fallback_model_id=p_fallback_model_id,enabled=p_enabled
    where id=p_policy_id returning * into v_policy;
    v_action := 'llm.routing.update';
  end if;

  insert into public.admin_audit_logs(
    actor_user_id,action,resource_type,resource_id,scope_type,correlation_id,outcome,metadata
  ) values (
    p_actor_user_id,v_action,'llm_routing_policy',v_policy.id::text,'platform',
    coalesce(nullif(p_correlation_id,''),gen_random_uuid()::text),'success',
    jsonb_build_object('task_type',v_policy.task_type,'model_id',v_policy.model_id,
      'fallback_model_id',v_policy.fallback_model_id,'priority',v_policy.priority,'enabled',v_policy.enabled)
  );

  return jsonb_build_object('id',v_policy.id,'task_type',v_policy.task_type,
    'model_id',v_policy.model_id,'fallback_model_id',v_policy.fallback_model_id,
    'priority',v_policy.priority,'enabled',v_policy.enabled);
end;
